/// Current UNIX timestamp in seconds (bridged to a2r_std::time::now_sec).
fn now_secs() -> u32 {
    return (time::now_sec() as u32);
}

/// a - b, clamped at 0 (mirrors u64::saturating_sub).
fn saturating_sub(a: u32, b: u32) -> u32 {
    if a >= b {
        return a - b;
    }
    return 0;
}

/// True when the status is the Paused variant.
fn is_paused(status: PipelineStatus) -> bool {
    match status {
        PipelineStatus::Paused(_at) => return true,
        _ => return false,
    };
}

/// True when the status is the Failed variant.
fn is_failed(status: PipelineStatus) -> bool {
    match status {
        PipelineStatus::Failed(_e) => return true,
        _ => return false,
    };
}

/// The role id the handoff target SHOULD be, given the exit routing.
/// None when there is no successor (last step with Next routing).
fn expected_target_role(eng: PipelineEngine, exit: ExitRouting) -> Option<String> {
    match exit {
        ExitRouting::Next => {
            let next_idx: u32 = eng.current_step + 1;
            if next_idx < (eng.flow.steps.len() as u32) {
                return Some(eng.flow.steps[(next_idx) as usize].clone().role_id);
            }
            return None;
        },
        ExitRouting::Loop(target_step_id, _max) => {
            match eng.flow.get_step_index(target_step_id.as_str()) {
                Some(idx) => return Some(eng.flow.steps[(idx) as usize].clone().role_id.clone()),
                None => return None,
            };
        },
    };
}
